-- ============================================================================
-- UCO Bank Realty Portal - Core Schema DDL
-- Database: Oracle Database 19c / 21c / 23c Enterprise Edition / XE
-- Execution Environment: SQL*Plus / Oracle SQL Developer / Toad
-- Target Environments: UAT, PRE-PROD, PRODUCTION
-- Notes:
--   - Uses Oracle Identity columns (GENERATED BY DEFAULT AS IDENTITY)
--   - In-database Oracle SecureFiles BLOB for project photos
--   - Five tables: realty_projects (approved only), realty_project_staging (maker working copy), realty_project_images, realty_audit_log, realty_login_audit
--   - Customer leads are NOT stored here: the bank's Home Loan page keeps them in the HRMS table LG_ENTRY_REVAMP (CHANNEL = 'REALTY')
--   - The only script a NEW database (UAT / production) needs. Run once as the application schema user.
-- ============================================================================

-- 1. REALTY_PROJECTS TABLE (MASTER): holds only APPROVED records (status APPROVED, or DELETED which is kept for the logs).
--    Everything a maker is still working on lives in REALTY_PROJECT_STAGING until a checker approves it.
CREATE TABLE realty_projects (
  id VARCHAR2(20) PRIMARY KEY,
  sr_no NUMBER,
  zone_name VARCHAR2(100),
  branch_name VARCHAR2(100),
  state_name VARCHAR2(100),
  city_name VARCHAR2(100),
  project_name VARCHAR2(255) NOT NULL,
  rera_no VARCHAR2(100),
  property_id VARCHAR2(100),
  type_of_unit VARCHAR2(100),
  approval_date DATE,
  total_inventory NUMBER,
  unsold_inventory NUMBER,
  inventory_as_on_date DATE,
  amenities CLOB,
  start_date DATE,
  completion_date DATE,
  apt_per_floor NUMBER,
  no_of_towers NUMBER,
  total_project_area VARCHAR2(100),
  carpet_min VARCHAR2(50),
  carpet_max VARCHAR2(50),
  buildup_min VARCHAR2(50),
  buildup_max VARCHAR2(50),
  dist_railway VARCHAR2(100),
  dist_airport VARCHAR2(100),
  avg_rate VARCHAR2(100),
  budget_min VARCHAR2(100),
  budget_max VARCHAR2(100),
  builder_name VARCHAR2(255),
  project_address VARCHAR2(500),
  pin_code VARCHAR2(10),
  promoter1 VARCHAR2(255),
  promoter2 VARCHAR2(255),
  promoter3 VARCHAR2(255),
  promoter4 VARCHAR2(255),
  promoter5 VARCHAR2(255),
  sales_exec_name VARCHAR2(255),
  sales_mobile VARCHAR2(15),
  sales_email VARCHAR2(255),
  website VARCHAR2(255),
  builder_rating VARCHAR2(50),
  builder_rating_out_of VARCHAR2(20),         -- the scale of the rating: shown as "rating / out of", e.g. 4 / 5
  video_url VARCHAR2(500),                    -- link to a project video (YouTube or any web address); customers open it in a new tab
  amenity_flags VARCHAR2(600),                -- Yes/No answers, e.g. Swimming Pool:Y,Gym:N (amenities stays as free text for "anything else")
  builder_bg CLOB,
  branch_head_name VARCHAR2(255),
  branch_head_number VARCHAR2(15),
  rel_exec_name VARCHAR2(255),
  rel_exec_number VARCHAR2(15),
  valid_upto DATE,
  renewal_pending VARCHAR2(20),
  approval_sought VARCHAR2(100),
  certificate_path VARCHAR2(500),
  floor_plan_path VARCHAR2(500),
  total_img_count NUMBER DEFAULT 0,
  verified_img_count NUMBER DEFAULT 0,
  status VARCHAR2(30) DEFAULT 'APPROVED' NOT NULL,   -- a master row is an APPROVED record, or DELETED (kept for the logs)
  is_active NUMBER(1) DEFAULT 1 NOT NULL,
  is_published NUMBER(1) DEFAULT 1 NOT NULL,
  created_by VARCHAR2(50),                           -- the maker who raised the project
  checked_by VARCHAR2(50),                           -- the checker who last approved it
  checker_comment VARCHAR2(1000),
  deleted_at TIMESTAMP,                              -- set when a checker approves a deletion
  deleted_by VARCHAR2(50),
  row_version NUMBER DEFAULT 0 NOT NULL,             -- optimistic locking
  created_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT chk_realty_inventory CHECK (unsold_inventory IS NULL OR total_inventory IS NULL OR unsold_inventory <= total_inventory)
);

-- 2. REALTY_PROJECT_STAGING: the maker's working table (maker-checker staging).
--     One row per request: CREATE (a new project), UPDATE (edit / unit reduction of an approved project) or
--     DELETE (deletion of an approved project). The maker edits THIS row until he sends it for approval; only when
--     a checker approves is it applied to REALTY_PROJECTS (insert / update / mark DELETED). Approved, rejected and
--     withdrawn rows stay here as the history of who asked for what.
CREATE TABLE realty_project_staging (
  id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  project_id VARCHAR2(20) NOT NULL,           -- the project code: allocated at CREATE, becomes realty_projects.id on approval
  request_type VARCHAR2(10) NOT NULL,         -- CREATE | UPDATE | DELETE
  status VARCHAR2(20) NOT NULL,               -- DRAFT | PENDING_APPROVAL | NEEDS_CORRECTION | APPROVED | REJECTED | WITHDRAWN
  zone_name VARCHAR2(100),
  branch_name VARCHAR2(100),
  state_name VARCHAR2(100),
  city_name VARCHAR2(100),
  project_name VARCHAR2(255),
  rera_no VARCHAR2(100),
  property_id VARCHAR2(100),
  type_of_unit VARCHAR2(100),
  approval_date DATE,
  total_inventory NUMBER,
  unsold_inventory NUMBER,
  inventory_as_on_date DATE,
  amenities CLOB,
  start_date DATE,
  completion_date DATE,
  apt_per_floor NUMBER,
  no_of_towers NUMBER,
  total_project_area VARCHAR2(100),
  carpet_min VARCHAR2(50),
  carpet_max VARCHAR2(50),
  buildup_min VARCHAR2(50),
  buildup_max VARCHAR2(50),
  dist_railway VARCHAR2(100),
  dist_airport VARCHAR2(100),
  avg_rate VARCHAR2(100),
  budget_min VARCHAR2(100),
  budget_max VARCHAR2(100),
  builder_name VARCHAR2(255),
  project_address VARCHAR2(500),
  pin_code VARCHAR2(10),
  promoter1 VARCHAR2(255),
  promoter2 VARCHAR2(255),
  promoter3 VARCHAR2(255),
  promoter4 VARCHAR2(255),
  promoter5 VARCHAR2(255),
  sales_exec_name VARCHAR2(255),
  sales_mobile VARCHAR2(15),
  sales_email VARCHAR2(255),
  website VARCHAR2(255),
  builder_rating VARCHAR2(50),
  builder_rating_out_of VARCHAR2(20),         -- the scale of the rating: shown as "rating / out of", e.g. 4 / 5
  video_url VARCHAR2(500),                    -- link to a project video (YouTube or any web address); customers open it in a new tab
  amenity_flags VARCHAR2(600),                -- Yes/No answers, e.g. Swimming Pool:Y,Gym:N (amenities stays as free text for "anything else")
  builder_bg CLOB,
  branch_head_name VARCHAR2(255),
  branch_head_number VARCHAR2(15),
  rel_exec_name VARCHAR2(255),
  rel_exec_number VARCHAR2(15),
  valid_upto DATE,
  renewal_pending VARCHAR2(20),
  approval_sought VARCHAR2(100),
  remove_image_ids VARCHAR2(500),             -- UPDATE: live photos to remove when approved
  reason VARCHAR2(1000 CHAR),                 -- DELETE / unit reduction: the maker's reason
  summary VARCHAR2(1000 CHAR),                -- what changes (filled when sent for approval)
  base_version NUMBER,                        -- UPDATE / DELETE: realty_projects.row_version when the draft was opened
  row_version NUMBER DEFAULT 0 NOT NULL,      -- optimistic locking (two checkers cannot both decide it)
  created_by VARCHAR2(50) NOT NULL,           -- the maker
  checked_by VARCHAR2(50),
  checker_comment VARCHAR2(1000 CHAR),
  created_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
  submitted_at TIMESTAMP,
  decided_at TIMESTAMP,
  CONSTRAINT chk_realty_staging_inv CHECK (unsold_inventory IS NULL OR total_inventory IS NULL OR unsold_inventory <= total_inventory)
);
CREATE INDEX idx_realty_staging_project ON realty_project_staging(project_id, status);
CREATE INDEX idx_realty_staging_status ON realty_project_staging(status, request_type);
-- at most ONE open request per project (the database enforces it, not only the application)
-- ux_realty_staging_one_open is Oracle-only (H2 cannot index an expression); the application enforces the rule on H2

-- 3. PROJECT IMAGES TABLE (SecureFiles BLOB Storage)
CREATE TABLE realty_project_images (
  id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  project_id VARCHAR2(20),                    -- set for a live (approved) photo
  staging_id NUMBER,                          -- set while the photo belongs to a maker's unapproved work (never shown to customers)
  file_kind VARCHAR2(20) DEFAULT 'PHOTO' NOT NULL,   -- PHOTO, BROCHURE (PDF) or FLOOR_PLAN (PDF)
  file_name VARCHAR2(255),
  mime_type VARCHAR2(100),
  file_size NUMBER(19,0),
  file_data BLOB,
  file_path VARCHAR2(500) NOT NULL,
  is_verified NUMBER(1) DEFAULT 0 NOT NULL,
  uploaded_by VARCHAR2(50),
  uploaded_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT fk_realty_img_project FOREIGN KEY (project_id) REFERENCES realty_projects(id) ON DELETE CASCADE,
  CONSTRAINT fk_realty_img_staging FOREIGN KEY (staging_id) REFERENCES realty_project_staging(id) ON DELETE CASCADE,
  CONSTRAINT chk_realty_image_owner CHECK ((project_id IS NULL AND staging_id IS NOT NULL) OR (project_id IS NOT NULL AND staging_id IS NULL))
);

-- 5. AUDIT LOG TABLE
CREATE TABLE realty_audit_log (
  id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  entity_type VARCHAR2(50) NOT NULL,
  entity_id VARCHAR2(100) NOT NULL,
  action VARCHAR2(50) NOT NULL,
  by_user VARCHAR2(50),
  old_val VARCHAR2(1000 CHAR),
  new_val VARCHAR2(1000 CHAR),
  created_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL
);

-- 6. LOGIN AUDIT TABLE (Security and authentication attempts)
CREATE TABLE realty_login_audit (
  id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  username VARCHAR2(100),
  ip_address VARCHAR2(50),
  success NUMBER(1) NOT NULL,
  remarks VARCHAR2(500 CHAR),
  login_time TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL
);

-- ============================================================================
-- PERFORMANCE INDEXES
-- ============================================================================
CREATE INDEX idx_realty_proj_status_pub ON realty_projects(status, is_active, is_published);
CREATE INDEX idx_realty_proj_zone ON realty_projects(zone_name);
CREATE INDEX idx_realty_proj_branch ON realty_projects(branch_name);
CREATE INDEX idx_realty_proj_geo ON realty_projects(state_name, city_name);
CREATE INDEX idx_realty_proj_img_pid ON realty_project_images(project_id);
CREATE INDEX idx_realty_img_staging ON realty_project_images(staging_id);
CREATE INDEX idx_realty_audit_entity ON realty_audit_log(entity_type, entity_id);
CREATE INDEX idx_realty_audit_created ON realty_audit_log(created_at DESC);
CREATE INDEX idx_realty_login_audit_time ON realty_login_audit(login_time DESC);
CREATE INDEX idx_realty_login_audit_user ON realty_login_audit(username);



-- ============================================================================
-- MOCK HRMS TABLES: for a DEVELOPER LAPTOP only (Docker Oracle). UAT and production already have the bank's real HRMS tables
-- (employee_contact_details, hrms_dba.employee_tenure); NEVER run this there.
--
-- Table and column names are exactly what HrmsRepository queries; column types and sizes follow the bank's own
-- "desc employee_contact_details" (EMPNO varchar2(6), POSTING_SOL_ID varchar2(4), SCALE_CODE varchar2(2),
-- CADRE_CODE varchar2(4), POSTING_REGION_NAME varchar2(50)). Only the columns the application reads are created.
-- Created in the current schema; the application also tries the hrms_dba. prefix.
-- Fill with 05_LOCAL_TEST_EMPLOYEES.sql.
-- WARNING: this also creates a fake LG_ENTRY_REVAMP (with fake REALTY leads in 05). The application tries the schema WITHOUT a prefix first,
-- so on a database that has the bank's real HRMS tables this stand-in would hide them. Never run 03/05 there.
-- ============================================================================

CREATE TABLE employee_contact_details (
  EMPNO               VARCHAR2(6)   NOT NULL PRIMARY KEY,
  NAME                VARCHAR2(100) NOT NULL,
  POSTING_SOL_ID      VARCHAR2(4)   NOT NULL,
  POSTING_SOL_DESC    VARCHAR2(100),
  SCALE_CODE          VARCHAR2(2),
  CADRE_CODE          VARCHAR2(4),
  POSTING_REGION_NAME VARCHAR2(50),
  DESIG               VARCHAR2(100),
  MOBILE_NO           VARCHAR2(15),
  E_MAIL              VARCHAR2(50),
  RETIRE_FLAG         VARCHAR2(2)
);

-- Optional enrichment tables (used when present; they override SOL / scale / designation of the row above)
CREATE TABLE employee_tenure (
  EMPNO         VARCHAR2(6) NOT NULL,
  POSTING_SOL   VARCHAR2(4),
  SCALE_CODE    VARCHAR2(2),
  TENURE_AS     VARCHAR2(100),
  EFF_FROM_DATE DATE,
  EFF_TO_DATE   DATE,
  STATUS_FLAG   CHAR(1) DEFAULT 'V'
);

-- The bank's lead table (our Home Loan button sends customers to the bank's page, which stores each lead here with CHANNEL = 'REALTY').
-- Only the columns the Leads page reads. The real table has about 60 columns; types follow the bank's "desc LG_ENTRY_REVAMP".
CREATE TABLE LG_ENTRY_REVAMP (
  LEAD_ID       VARCHAR2(20) NOT NULL PRIMARY KEY,
  CRE_DT        DATE,
  REF_NAME      VARCHAR2(250),
  STATE         VARCHAR2(50),
  DISTRICT      VARCHAR2(100),
  MOBILE_NO     VARCHAR2(12),
  EMAIL         VARCHAR2(50),
  FACILITY_INT  VARCHAR2(50),
  LEAD_STATUS   VARCHAR2(2),            -- empty in the bank's data
  STATUS        VARCHAR2(20),           -- the real status (the bank's values such as OTP_VERIFIED, SB, CC)
  TENT_LOAN_AMT NUMBER(20,2),
  SUBMIT_DATE   DATE,
  CHANNEL       VARCHAR2(50),
  LOANAMOUNT    VARCHAR2(200)
);

-- ============================================================================
-- LOCAL TEST EMPLOYEES for a developer machine (MacBook): the application reads these rows exactly as it reads the bank's HRMS tables.
-- NOT for UAT or production: those environments already have the real data in the bank's HRMS tables.
-- Requires 03_CREATE_HRMS_MOCK_TABLES.sql first. scripts/dev-start.sh (Oracle) and scripts/h2_schema.py (H2) load 03 and 05 for you;
-- sign in with the employee number and the local test OTP, or open /entry?Value=<token> (token = encrypted  emp_id=<EMPNO>&sol_id=<SOL>, see TESTING_GUIDE.md).
-- The employee NUMBERS and postings are the REAL UAT testers (found in the UAT HRMS table, so the same numbers work on the laptop and on UAT);
-- the names are invented. 7103 stands in for the DIT SOL 7115 (nobody is posted at 7115 in UAT; see uco.rbac.superadmin-sols).
-- Idempotent (MERGE).
--
--   EMPNO   Expected role      SOL / posting
--   55012   SUPERADMIN_DIT     7103 (DIT)
--   54534   HO_MARKETING       8028 (HO Marketing and Wealth Management), Scale 3
--   53484   HO_MARKETING       8028, Scale 4
--   58382   HO_RETAIL          8001 (HO Retail Banking), Scale 3
--   51373   HO_RETAIL          8001, Scale 4
--   52260   ZO_MAKER           7010 (DURGAPUR ZONAL OFFICE), Scale 1
--   45195   ZO_CHECKER         7010 (DURGAPUR ZONAL OFFICE), Scale 4
--   62100   (no access: scale 0) 7010
--   68696   ZO_MAKER           7014 (RAIPUR ZONAL OFFICE), Scale 1
--   45321   ZO_CHECKER         7014 (RAIPUR ZONAL OFFICE), Scale 4
--   41459   (no access: scale 0) 7014
--   600001  (no access: branch SOL) 1234 (TEST BRANCH)       [invented]
--   600003  (no access: retired)   7010 (RETIRE_FLAG=RT)      [invented]
-- ============================================================================



