WHEN MATCHED THEN UPDATE SET NAME='UAT Raipur Scale 0', POSTING_SOL_ID='7014', POSTING_SOL_DESC='RAIPUR ZONAL OFFICE', SCALE_CODE='0', CADRE_CODE='CLRK',
  POSTING_REGION_NAME='RAIPUR', DESIG='Clerk', MOBILE_NO='9000000010', E_MAIL='staff.41459@uco.bank.in', RETIRE_FLAG='N'
WHEN NOT MATCHED THEN INSERT (EMPNO, NAME, POSTING_SOL_ID, POSTING_SOL_DESC, SCALE_CODE, CADRE_CODE, POSTING_REGION_NAME, DESIG, MOBILE_NO, E_MAIL, RETIRE_FLAG)
  VALUES ('41459','UAT Raipur Scale 0','7014','RAIPUR ZONAL OFFICE','0','CLRK','RAIPUR','Clerk','9000000010','staff.41459@uco.bank.in','N');

